// MIT first-party static metadata API. Target assemblies are parsed, never loaded for execution.
using System.Security.Cryptography;using System.Text;using System.Text.Json;using System.Text.Json.Serialization;using dnlib.DotNet;using dnlib.DotNet.Emit;
sealed class Plan {public int Schema{get;set;}public string Mode{get;set;}="query";public string Input{get;set;}="";public string? Other{get;set;}public string View{get;set;}="overview";public string? Type{get;set;}public uint? Token{get;set;}public string? Filter{get;set;}public int Limit{get;set;}=50;public int Offset{get;set;}=0;}
sealed class NoAssemblyResolution:IAssemblyResolver {public AssemblyDef? Resolve(IAssembly assembly,ModuleDef sourceModule)=>null;}
static class Program {
 static readonly JsonSerializerOptions Json=new(){PropertyNamingPolicy=JsonNamingPolicy.CamelCase,DefaultIgnoreCondition=JsonIgnoreCondition.WhenWritingNull};
 static string Hash(string value)=>Convert.ToHexStringLower(SHA256.HashData(Encoding.UTF8.GetBytes(value)));
 static string Token(MethodDef method)=>"0x"+method.MDToken.Raw.ToString("x8");
 static object? ImportState(MethodDef method)=>method.HasImplMap?new {module=method.ImplMap.Module.Name.ToString(),entryPoint=method.ImplMap.Name.ToString(),attributes=method.ImplMap.Attributes.ToString()}:null;
 static object Import(MethodDef method)=>new {module=method.ImplMap.Module.Name.ToString(),entryPoint=method.ImplMap.Name.ToString(),attributes=method.ImplMap.Attributes.ToString(),signature=method.FullName,token=Token(method)};
 static string OperandAt(object? operand,Func<Instruction,int> index)=>operand switch {null=>"",Instruction i=>"label:"+index(i),Instruction[] a=>string.Join(",",a.Select(i=>"label:"+index(i))),IMethod m=>"method:"+m.FullName,IField f=>"field:"+f.FullName,ITypeDefOrRef t=>"type:"+t.FullName,TypeSig t=>"type:"+t.FullName,dnlib.DotNet.Emit.Local local=>"local:"+local.Index+":"+local.Type.FullName,Parameter parameter=>"parameter:"+parameter.Index+":"+parameter.Type.FullName,string s=>"string:"+JsonSerializer.Serialize(s),IFormattable f=>f.ToString(null,System.Globalization.CultureInfo.InvariantCulture)??"",_=>operand.ToString()??""};
 static string Operand(object? operand,IList<Instruction> instructions)=>OperandAt(operand,instructions.IndexOf);
 static object? Body(MethodDef method){if(method.Body is null)return null;var body=method.Body;var instructions=body.Instructions;if(instructions.Count>100000)throw new InvalidOperationException("A method exceeds 100000 instructions; narrow the comparison/query");var indices=instructions.Select((i,n)=>(i,n)).ToDictionary(p=>p.i,p=>p.n);int At(Instruction? i)=>i is null?instructions.Count:indices[i];
  return new{initLocals=body.InitLocals,locals=body.Variables.Select(v=>v.Type.FullName).ToArray(),instructions=instructions.Select(i=>i.IsLdcI4()?new{opcode="ldc.i4",operand=i.GetLdcI4Value().ToString(System.Globalization.CultureInfo.InvariantCulture)}:new{opcode=i.OpCode.OperandType is OperandType.ShortInlineBrTarget?i.OpCode.Name.Replace(".s",""):i.OpCode.Name,operand=OperandAt(i.Operand,i=>indices[i])}).ToArray(),handlers=body.ExceptionHandlers.Select(h=>new{kind=h.HandlerType.ToString(),@try=At(h.TryStart),tryEnd=At(h.TryEnd),handler=At(h.HandlerStart),handlerEnd=At(h.HandlerEnd),filter=At(h.FilterStart),catchType=h.CatchType?.FullName}).ToArray()};
 }
 static string Fingerprint(MethodDef method)=>Hash(JsonSerializer.Serialize(new{signature=method.FullName,attributes=method.Attributes.ToString(),implementation=method.ImplAttributes.ToString(),import=method.HasImplMap?new{module=method.ImplMap.Module.Name.ToString(),entryPoint=method.ImplMap.Name.ToString(),attributes=method.ImplMap.Attributes.ToString()}:null,body=Body(method)},Json));
 static bool Matches(Plan p,MethodDef method)=>(p.Type is null||method.DeclaringType.FullName==p.Type)&&(!p.Token.HasValue||method.MDToken.Raw==p.Token)&&(p.Filter is null||method.FullName.Contains(p.Filter,StringComparison.Ordinal));
 static object Query(Plan p,ModuleDefMD module){var types=module.GetTypes().Take(100001).ToArray();if(types.Length>100000)throw new InvalidOperationException("Assembly exceeds the 100000-type query bound");var methods=types.SelectMany(t=>t.Methods).ToArray();if(methods.Length>1000000)throw new InvalidOperationException("Assembly exceeds the million-method query bound");var scope="Static dnlib metadata/IL only; no target execution, dependency resolution or PDB loading. Tokens belong to this exact module. Structural equality is not semantic equivalence.";
  object Result(object data)=>new{state="completed",complete=true,view=p.View,data,scope};object Rows(object[] rows)=>new{state="completed",complete=true,view=p.View,items=rows.Skip(p.Offset).Take(p.Limit),total=rows.Length,limit=p.Limit,offset=p.Offset,truncated=p.Offset+p.Limit<rows.Length,scope};
  if(p.View=="overview")return Result(new{assembly=module.Assembly?.FullName,module=module.Name.ToString(),mvid=module.Mvid,metadataRuntimeVersion=module.RuntimeVersion,targetFramework=module.Assembly?.CustomAttributes.Find("System.Runtime.Versioning.TargetFrameworkAttribute")?.ConstructorArguments.FirstOrDefault().Value?.ToString(),machine=module.Machine.ToString(),ilOnly=module.IsILOnly,types=types.Length,methods=methods.Length,imports=methods.Count(m=>m.HasImplMap),entryPoint=module.EntryPoint?.FullName,references=module.GetAssemblyRefs().Take(256).Select(a=>a.FullName).ToArray(),resources=module.Resources.Take(256).Select(r=>r.Name.ToString()).ToArray(),referenceResourceBound=256});
  if(p.View=="types")return Rows(types.Where(t=>(p.Type is null||t.FullName==p.Type)&&(p.Filter is null||t.FullName.Contains(p.Filter,StringComparison.Ordinal))).Select(t=>(object)new{name=t.FullName,token="0x"+t.MDToken.Raw.ToString("x8"),baseType=t.BaseType?.FullName,attributes=t.Attributes.ToString(),methods=t.Methods.Count,fields=t.Fields.Count}).ToArray());
  if(p.View=="methods")return Rows(methods.Where(m=>Matches(p,m)).Select(m=>(object)new{name=m.FullName,token=Token(m),declaringType=m.DeclaringType.FullName,hasBody=m.HasBody,isImport=m.HasImplMap}).ToArray());
  if(p.View=="imports")return Rows(methods.Where(m=>m.HasImplMap&&Matches(p,m)).Select(Import).ToArray());
  if(p.View!="method"||!p.Token.HasValue)throw new InvalidOperationException("Method view requires a MethodDef token");var method=methods.SingleOrDefault(m=>Matches(p,m))??throw new InvalidOperationException("Selected MethodDef was not found in the exact captured module");var instructions=method.Body?.Instructions??[];return new{state="completed",complete=true,view=p.View,method=method.FullName,token=Token(method),attributes=method.Attributes.ToString(),implementation=method.ImplAttributes.ToString(),import=method.HasImplMap?Import(method):null,instructions=instructions.Skip(p.Offset).Take(p.Limit).Select(i=>new{offset=i.Offset,opcode=i.OpCode.Name,operand=Operand(i.Operand,instructions)}).ToArray(),totalInstructions=instructions.Count,limit=p.Limit,offset=p.Offset,truncated=p.Offset+p.Limit<instructions.Count,normalizedBodySha256=method.HasBody?Hash(JsonSerializer.Serialize(Body(method),Json)):null,parameters=method.Parameters.Select(v=>new{index=v.Index,name=v.Name,type=v.Type.FullName}).ToArray(),scope};
 }
 static object Compare(Plan p,ModuleDefMD left,ModuleDefMD right){Dictionary<string,MethodDef> Index(ModuleDefMD m){var types=m.GetTypes().Take(100001).ToArray();if(types.Length>100000)throw new InvalidOperationException("Assembly exceeds comparison type bound");var methods=types.SelectMany(t=>t.Methods).Where(method=>Matches(p,method)).Take(100001).ToArray();if(methods.Length>100000)throw new InvalidOperationException("Comparison exceeds 100000 methods; narrow with a type/filter");return methods.ToDictionary(m=>m.FullName,StringComparer.Ordinal);}
  var a=Index(left);var b=Index(right);var changes=new List<object>();int unchanged=0;foreach(var name in a.Keys.Union(b.Keys).Order(StringComparer.Ordinal)){a.TryGetValue(name,out var l);b.TryGetValue(name,out var r);if(l is null||r is null){changes.Add(new{name,state=l is null?"added":"removed",left=l is null?null:Token(l),right=r is null?null:Token(r)});continue;}if(Fingerprint(l)==Fingerprint(r)){unchanged++;continue;}changes.Add(new{name,state="changed",left=Token(l),right=Token(r),ilChanged=Hash(JsonSerializer.Serialize(Body(l),Json))!=Hash(JsonSerializer.Serialize(Body(r),Json)),importChanged=JsonSerializer.Serialize(ImportState(l),Json)!=JsonSerializer.Serialize(ImportState(r),Json)});}
  var ar=left.GetAssemblyRefs().Select(a=>a.FullName).Order(StringComparer.Ordinal).ToArray();var br=right.GetAssemblyRefs().Select(a=>a.FullName).Order(StringComparer.Ordinal).ToArray();return new{state="completed",complete=true,leftAssembly=left.Assembly?.FullName,rightAssembly=right.Assembly?.FullName,unchanged,total=changes.Count,items=changes.Skip(p.Offset).Take(p.Limit).ToArray(),limit=p.Limit,offset=p.Offset,truncated=p.Offset+p.Limit<changes.Count,referencesChanged=!ar.SequenceEqual(br),leftReferences=ar,rightReferences=br,scope="Static structural comparison by exact managed signature. Signature changes appear as removed/added methods; operands resolve to names and branch/local indices rather than unstable metadata RIDs. Dependencies/runtime/environment can change behavior despite equal IL. No target execution or automatic publication."};
 }
 public static int Main(string[] args){try{if(args.Length!=1||!Path.IsPathFullyQualified(args[0])||new FileInfo(args[0]).Length>16384)throw new InvalidOperationException("A bounded absolute private plan is required");var p=JsonSerializer.Deserialize<Plan>(File.ReadAllText(args[0]),new JsonSerializerOptions{PropertyNameCaseInsensitive=true})??throw new InvalidOperationException("Missing plan");if(p.Schema!=1||!Path.IsPathFullyQualified(p.Input)||new FileInfo(p.Input).Length>64*1024*1024||p.Limit<1||p.Limit>1000||p.Offset<0)throw new InvalidOperationException("Invalid metadata query bounds");var options=new ModuleCreationOptions{TryToLoadPdbFromDisk=false,Context=new ModuleContext(new NoAssemblyResolution())};using var input=ModuleDefMD.Load(p.Input,options);object result;if(p.Mode=="query")result=Query(p,input);else if(p.Mode=="compare"&&p.Other is not null&&Path.IsPathFullyQualified(p.Other)&&new FileInfo(p.Other).Length<=64*1024*1024){using var other=ModuleDefMD.Load(p.Other,options);result=Compare(p,input,other);}else throw new InvalidOperationException("Unknown static metadata operation");Console.WriteLine(JsonSerializer.Serialize(result,Json));return 0;}catch(Exception error){Console.WriteLine(JsonSerializer.Serialize(new{state="failed",error=error.Message.Length>4096?error.Message[..4096]:error.Message},Json));return 70;}}
}
